package jp.terada.midnitelogger;
public class ClassicReader {private final Modbus m; public ClassicReader(Modbus.L l){m=new Modbus(l);} private static int s16(int x){return (short)x;} private static long u32(int lo,int hi){return ((long)hi<<16)|(lo&65535L);} private static long s32(int lo,int hi){return (int)u32(lo,hi);}
 public Record read()throws Exception{int[] b=m.read(Config.CLASSIC_IP,Config.MODBUS_PORT,Config.UNIT_ID,4114,28);int[] w=m.read(Config.CLASSIC_IP,Config.MODBUS_PORT,Config.UNIT_ID,4364,7);int[] p=m.read(Config.CLASSIC_IP,Config.MODBUS_PORT,Config.UNIT_ID,4390,1);Record r=new Record();r.ts=Time.now();r.batteryV=b[0]/10.0;r.pvV=b[1]/10.0;r.classicA=s16(b[2])/10.0;r.dailyKwh=b[3]/10.0;r.watts=b[4];r.chargeStage=(b[5]>>8)&255;r.classicState=b[5]&255;r.pvA=b[6]/10.0;r.lastVocV=b[7]/10.0;r.highestPvV=b[8]/10.0;r.dailyAh=b[10];r.lifetimeKwh=u32(b[11],b[12]);r.lifetimeAh=u32(b[13],b[14]);r.infoFlags=u32(b[15],b[16]);r.batteryTemp=s16(b[17])/10.0;r.fetTemp=s16(b[18])/10.0;r.pcbTemp=s16(b[19])/10.0;r.minutesNoPv=b[20];r.floatSeconds=b[23];r.resetReason=b[27];r.wbPositiveAh=u32(w[0],w[1]);r.wbNegativeAh=u32(w[2],w[3]);r.wbNetAh=s32(w[4],w[5]);r.wbA=s16(w[6])/10.0;r.wbPreciseA=s16(p[0])/100.0;return r;}}
